      "district": "Ratnapura",
      "description": "Housed in the historic Ehelepola Walauwa—an authentic 17th-century Kandyan aristocratic mansion that belonged to Ehelepola Disawa—the National Museum of Ratnapura documents Sri Lanka’s legendary 2,500-year history as the gemstone capital of the world. Exhibits showcase precious blue sapphires, rubies, and alexandrites alongside traditional bamboo gem pit mining equipment and prehistoric fossils of mammoths, rhinoceroses, and hippos unearthed from local gem gravels.",
