      "activities": [
        "Gemological study and museum antiquities exploration",
        "Learning about traditional Sabaragamuwa gem mining techniques (illama washing)"
      ],
      "travelTips": [
        "Located conveniently along the Colombo-Batticaloa highway (A4) within Ratnapura town."
      ]
